#include <sstream>
#include <string>
#include <vector>

std::string validationSummary(const std::vector<int>& left, const std::vector<int>& right) {
    std::vector<int> merged;
    size_t leftIndex = 0;
    size_t rightIndex = 0;
    while (leftIndex < left.size() && rightIndex < right.size()) {
        if (left[leftIndex] <= right[rightIndex]) {
            merged.push_back(left[leftIndex++]);
        } else {
            merged.push_back(right[rightIndex++]);
        }
    }
    while (leftIndex < left.size()) merged.push_back(left[leftIndex++]);
    while (rightIndex < right.size()) merged.push_back(right[rightIndex++]);
    std::ostringstream output;
    for (size_t index = 0; index < merged.size(); index++) {
        if (index > 0) output << ",";
        output << merged[index];
    }
    return output.str();
}
